export function parseRecord(record) {
    const fields = [];
    let i = 0;

    while (true) {
        let field = "";

        if (record[i] === '"') {
            i++;
            let closed = false;
            while (i < record.length) {
                const char = record[i++];
                if (char !== '"') {
                    field += char;
                } else if (record[i] === '"') {
                    field += '"';
                    i++;
                } else {
                    closed = true;
                    break;
                }
            }
            if (!closed) {
                throw new SyntaxError("Unterminated quoted field");
            }
            if (i < record.length && record[i] !== ",") {
                throw new SyntaxError("Unexpected character after closing quote");
            }
        } else {
            while (i < record.length && record[i] !== ",") {
                const char = record[i++];
                if (char === '"') {
                    throw new SyntaxError("Quote inside unquoted field");
                }
                if (char === "\r" || char === "\n") {
                    throw new SyntaxError("Record separator outside quoted field");
                }
                field += char;
            }
        }

        fields.push(field);
        if (i === record.length) {
            return fields;
        }
        i++;
    }
}

