export function parseRecord(record) {
    const fields = [];
    let field = "";
    let quoted = false;
    let closed = false;

    for (let i = 0; i < record.length; i++) {
        const char = record[i];
        if (quoted) {
            if (char !== '"') {
                field += char;
            } else if (record[i + 1] === '"') {
                field += '"';
                i++;
            } else {
                quoted = false;
                closed = true;
            }
        } else if (char === ",") {
            fields.push(field);
            field = "";
            closed = false;
        } else if (closed) {
            throw new SyntaxError("Unexpected character after closing quote");
        } else if (char === '"') {
            if (field.length !== 0) {
                throw new SyntaxError("Quote inside unquoted field");
            }
            quoted = true;
        } else {
            field += char;
        }
    }

    if (quoted) {
        throw new SyntaxError("Unterminated quoted field");
    }
    fields.push(field);
    return fields;
}

