export async function retry(operation, { attempts, signal, sleep }) {
    if (!Number.isInteger(attempts) || attempts <= 0) {
        throw new RangeError('attempts must be a positive integer');
    }

    function checkCancellation() {
        if (signal?.aborted) { throw signal.reason; }
    }

    async function wait() {
        checkCancellation();
        let onAbort;
        try {
            await new Promise((resolve, reject) => {
                onAbort = () => reject(signal.reason);
                signal?.addEventListener('abort', onAbort, { once: true });
                if (signal?.aborted) {
                    onAbort();
                    return;
                }
                Promise.resolve(sleep(10, signal)).then(resolve, reject);
            });
        } catch (error) {
            checkCancellation();
            throw error;
        } finally {
            signal?.removeEventListener('abort', onAbort);
        }
        checkCancellation();
    }

    for (let index = 0; index < attempts; index += 1) {
        checkCancellation();
        let value;
        try {
            value = await operation(index, signal);
        } catch (error) {
            checkCancellation();
            if (index === attempts - 1) { throw error; }
            await wait();
            continue;
        }
        checkCancellation();
        return value;
    }
}

