export function migrate(settings) {
    if (settings.version !== 1 && settings.version !== 2) {
        throw new Error("Unsupported or missing settings version");
    }

    const result = structuredClone(settings);
    if (result.version === 2) {
        return result;
    }

    if (Object.hasOwn(result, "theme")) {
        if (!Object.hasOwn(result, "display")) {
            result.display = {};
        }
        result.display.theme = result.theme;
        delete result.theme;
    }
    result.version = 2;
    return result;
}

