export function safeEntry(name) {
    if (typeof name !== "string" || name.length === 0 || /[\\:\u0000-\u001f\u007f-\u009f]/u.test(name)) {
        return false;
    }

    const path = name.endsWith("/") ? name.slice(0, -1) : name;
    return path.split("/").every(segment =>
        segment.length > 0 &&
        segment !== "." &&
        segment !== ".." &&
        !segment.endsWith(".") &&
        !segment.endsWith(" ")
    );
}

