export function memoizeReport(load) {
    const values = new Map();
    return (tenant, query) => {
        const normalizedQuery = {
            labels: [...new Set(query.labels)].sort(),
            archived: query.archived
        };
        const key = JSON.stringify([tenant, normalizedQuery.labels, normalizedQuery.archived]);
        if (!values.has(key)) {
            const pending = Promise.resolve()
                .then(() => load(tenant, normalizedQuery))
                .catch(error => {
                    if (values.get(key) === pending) values.delete(key);
                    throw error;
                });
            values.set(key, pending);
        }
        return values.get(key);
    };
}

