export function* take(source, count) {
    if (count === 0) { return; }
    const iterator = source[Symbol.iterator]();
    let exhausted = false;
    let threw = false;
    try {
        for (let index = 0; index < count; index += 1) {
            const item = iterator.next();
            if (item.done) { exhausted = true; return; }
            yield item.value;
        }
    } catch (error) {
        threw = true;
        throw error;
    } finally {
        if (!exhausted) {
            try {
                iterator.return?.();
            } catch (error) {
                if (!threw) { throw error; }
            }
        }
    }
}

