export function receiptFresh(before, after) {
    if (before.head !== after.head) return false;

    const beforePaths = Object.keys(before.inputs);
    const afterPaths = Object.keys(after.inputs);
    return beforePaths.length === afterPaths.length && beforePaths.every(path =>
        Object.prototype.hasOwnProperty.call(after.inputs, path) &&
        before.inputs[path] === after.inputs[path]
    );
}

