export function parseRecord(record) {
    const fields = [];
    let index = 0;

    while (true) {
        let field = "";

        if (record[index] === '"') {
            index++;
            let closed = false;

            while (index < record.length) {
                const char = record[index++];
                if (char !== '"') {
                    field += char;
                } else if (record[index] === '"') {
                    field += '"';
                    index++;
                } else {
                    closed = true;
                    break;
                }
            }

            if (!closed) {
                throw new SyntaxError("Unterminated quoted field");
            }
            if (index < record.length && record[index] !== ",") {
                throw new SyntaxError("Unexpected character after closing quote");
            }
        } else {
            while (index < record.length && record[index] !== ",") {
                if (record[index] === '"') {
                    throw new SyntaxError("Quote inside unquoted field");
                }
                field += record[index++];
            }
        }

        fields.push(field);
        if (index === record.length) {
            return fields;
        }
        index++;
    }
}

