export async function applyBatch(store, changes) {
    const names = changes.map((change) => change.name);
    if (new Set(names).size !== names.length) {
        throw new Error("Duplicate target names are invalid");
    }
    const before = await snapshot(store, names);
    try {
        for (const change of changes) { await store.write(change.name, change.value); }
        return true;
    } catch (error) {
        const errors = [error];
        for (let i = before.length - 1; i >= 0; i--) {
            const item = before[i];
            try {
                if (item.exists) { await store.write(item.name, item.value); } else { await store.remove(item.name); }
            } catch (rollbackError) {
                errors.push(rollbackError);
            }
        }
        if (errors.length > 1) {
            throw new AggregateError(errors, "Batch write and rollback failed");
        }
        throw error;
    }
}

