import { StringDecoder } from "node:string_decoder";

export function createLines(emit) {
    const decoder = new StringDecoder("utf8");
    let pending = "";
    let skipLF = false;
    let ended = false;

    function process(text) {
        let start = 0;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (skipLF) {
                skipLF = false;
                if (char === "\n") {
                    start = i + 1;
                    continue;
                }
            }
            if (char === "\r" || char === "\n") {
                const line = pending + text.slice(start, i);
                pending = "";
                start = i + 1;
                skipLF = char === "\r";
                emit(line);
            }
        }
        pending += text.slice(start);
    }

    return {
        write(chunk) {
            if (ended) { throw new Error("Cannot write after end"); }
            process(decoder.write(chunk));
        },
        end() {
            if (ended) { return; }
            ended = true;
            process(decoder.end());
            if (pending !== "") {
                const line = pending;
                pending = "";
                emit(line);
            }
        },
    };
}

