export function executionSpecDigest(spec) {
    return verificationDigest({
        command: spec.command,
        cwd: spec.cwd,
        shell: spec.shell,
        dialect: spec.dialect,
        timeoutSeconds: spec.timeoutSeconds,
    });
}

export function captureInputs(root, declarations) {
