export async function retry(operation, { attempts, signal, sleep }) {
    if (!Number.isInteger(attempts) || attempts < 1) {
        throw new RangeError('attempts must be a positive integer');
    }

    function checkCancellation() {
        if (signal?.aborted) { throw signal.reason; }
    }

    async function run(callback) {
        checkCancellation();
        if (!signal) { return await callback(); }

        let onAbort;
        const cancellation = new Promise((resolve, reject) => {
            onAbort = () => reject(signal.reason);
            signal.addEventListener('abort', onAbort, { once: true });
        });
        try {
            const work = Promise.resolve().then(() => {
                checkCancellation();
                return callback();
            });
            const result = await Promise.race([work, cancellation]);
            checkCancellation();
            return result;
        } finally {
            signal.removeEventListener('abort', onAbort);
        }
    }

    checkCancellation();
    for (let index = 0; index < attempts; index += 1) {
        try {
            const result = await run(() => operation(index, signal));
            checkCancellation();
            return result;
        } catch (error) {
            checkCancellation();
            if (index === attempts - 1) { throw error; }
        }
        await run(() => sleep(10, signal));
    }
}

