export async function applyBatch(store, changes) {
    const names = changes.map((change) => change.name);
    if (new Set(names).size !== names.length) {
        throw new Error("Duplicate target names are invalid");
    }
    const before = await snapshot(store, names);
    try {
        for (const change of changes) {
            await store.write(change.name, change.value);
        }
        return true;
    } catch (error) {
        const rollbackErrors = [];
        for (let index = before.length - 1; index >= 0; index--) {
            const item = before[index];
            try {
                if (item.exists) {
                    await store.write(item.name, item.value);
                } else {
                    await store.remove(item.name);
                }
            } catch (rollbackError) {
                rollbackErrors.push(rollbackError);
            }
        }
        if (rollbackErrors.length > 0) {
            throw new AggregateError([error, ...rollbackErrors], "Batch write and rollback failed");
        }
        throw error;
    }
}

