import { StringDecoder } from "node:string_decoder";

export function createLines(emit) {
    const decoder = new StringDecoder("utf8");
    let pending = "";
    let skipLF = false;
    let ended = false;

    function consume(text) {
        for (const char of text) {
            if (skipLF) {
                skipLF = false;
                if (char === "\n") continue;
            }
            if (char === "\r" || char === "\n") {
                const line = pending;
                pending = "";
                skipLF = char === "\r";
                emit(line);
            } else {
                pending += char;
            }
        }
    }

    return {
        write(chunk) {
            if (ended) throw new Error("Cannot write after end");
            consume(decoder.write(chunk));
        },
        end() {
            if (ended) return;
            ended = true;
            consume(decoder.end());
            if (pending !== "") {
                const line = pending;
                pending = "";
                emit(line);
            }
        },
    };
}

