export function parseRecord(record) {
    const fields = [];
    let field = "";
    let state = "start";

    for (let i = 0; i < record.length; i++) {
        const char = record[i];
        if (state === "quoted") {
            if (char === '"') {
                if (record[i + 1] === '"') {
                    field += '"';
                    i++;
                } else {
                    state = "closed";
                }
            } else {
                field += char;
            }
        } else if (char === ",") {
            fields.push(field);
            field = "";
            state = "start";
        } else if (state === "closed") {
            throw new SyntaxError("Unexpected character after closing quote");
        } else if (char === '"') {
            if (state !== "start") {
                throw new SyntaxError("Quote inside unquoted field");
            }
            state = "quoted";
        } else {
            if (char === "\r" || char === "\n") {
                throw new SyntaxError("Record separator inside unquoted field");
            }
            field += char;
            state = "unquoted";
        }
    }

    if (state === "quoted") {
        throw new SyntaxError("Unterminated quoted field");
    }
    fields.push(field);
    return fields;
}

