export class Events {
    #listeners = new Map();
    on(name, callback) {
        const listener = (...args) => callback(...args);
        const list = this.#listeners.get(name) ?? [];
        list.push(listener);
        this.#listeners.set(name, list);
        return () => { this.#listeners.set(name, (this.#listeners.get(name) ?? []).filter((item) => item !== listener)); };
    }
    once(name, callback) {
        let fired = false;
        const remove = this.on(name, (...args) => {
            if (fired) return;
            fired = true;
            remove();
            callback(...args);
        });
        return remove;
    }
    emit(name, ...args) {
        for (const callback of [...(this.#listeners.get(name) ?? [])]) { callback(...args); }
    }
}

