import { StringDecoder } from "node:string_decoder";

export function createLines(emit) {
    const decoder = new StringDecoder("utf8");
    let pending = "";
    let afterCR = false;
    let ended = false;

    function consume(text) {
        let start = 0;
        for (let i = 0; i < text.length; i++) {
            const char = text[i];
            if (afterCR) {
                afterCR = false;
                if (char === "\n") {
                    start = i + 1;
                    continue;
                }
            }
            if (char === "\r" || char === "\n") {
                const line = pending + text.slice(start, i);
                pending = "";
                start = i + 1;
                afterCR = char === "\r";
                emit(line);
            }
        }
        pending += text.slice(start);
    }

    return {
        write(chunk) {
            if (ended) throw new Error("Cannot write after end");
            consume(decoder.write(chunk));
        },
        end() {
            if (ended) return;
            ended = true;
            consume(decoder.end());
            if (pending.length > 0) {
                const line = pending;
                pending = "";
                emit(line);
            }
        },
    };
}

