export function parseRecord(record) {
    const fields = [];
    let position = 0;

    while (true) {
        let field = "";
        if (record[position] === '"') {
            position++;
            let closed = false;
            while (position < record.length) {
                const character = record[position++];
                if (character !== '"') {
                    field += character;
                } else if (record[position] === '"') {
                    field += '"';
                    position++;
                } else {
                    closed = true;
                    break;
                }
            }
            if (!closed) {
                throw new SyntaxError("Unterminated quoted field");
            }
            if (position < record.length && record[position] !== ",") {
                throw new SyntaxError("Unexpected character after closing quote");
            }
        } else {
            while (position < record.length && record[position] !== ",") {
                if (record[position] === '"') {
                    throw new SyntaxError("Quote inside unquoted field");
                }
                field += record[position++];
            }
        }

        fields.push(field);
        if (position === record.length) {
            return fields;
        }
        position++;
    }
}

