export async function mapLimit(items, limit, work) {
    if (!Number.isInteger(limit) || limit <= 0) {
        throw new RangeError('limit must be a positive integer');
    }

    const results = new Array(items.length);
    let nextIndex = 0;
    let failed = false;
    let firstError;

    async function run() {
        while (!failed && nextIndex < results.length) {
            const index = nextIndex++;
            try {
                results[index] = await work(items[index], index);
            } catch (error) {
                if (!failed) {
                    failed = true;
                    firstError = error;
                }
            }
        }
    }

    const workers = [];
    for (let worker = 0; worker < Math.min(limit, results.length); worker++) {
        workers.push(run());
    }
    await Promise.all(workers);
    if (failed) {
        throw firstError;
    }
    return results;
}

