        checkCancellation();
        let result;
        try {
            result = await operation(index, signal);
        } catch (error) {
            checkCancellation();
            if (index === attempts - 1) { throw error; }
            if (!signal) {
                await sleep(10, signal);
            } else {
                let onAbort;
                try {
                    await new Promise((resolve, reject) => {
                        onAbort = () => reject(signal.reason);
                        signal.addEventListener('abort', onAbort, { once: true });
                        if (signal.aborted) {
                            onAbort();
                            return;
                        }
                        Promise.resolve(sleep(10, signal)).then(resolve, reject);
                    });
                } finally {
                    signal.removeEventListener('abort', onAbort);
                }
            }
            checkCancellation();
            continue;
        }
        checkCancellation();
        return result;
    }
}

