export function migrate(settings) {
    if (settings.version !== 1 && settings.version !== 2) {
        throw new Error("Unsupported settings version");
    }

    const result = JSON.parse(JSON.stringify(settings));
    if (settings.version === 2) {
        return result;
    }

    if (Object.prototype.hasOwnProperty.call(settings, "theme")) {
        result.display = { ...result.display, theme: result.theme };
        delete result.theme;
    }
    result.version = 2;
    return result;
}

